public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node is null
    if (node == null) {
        return null;
    }

    // Get the left child of the node
    TreeNode<T> leftChild = node.getLeft();

    // Check if the left child is null
    if (leftChild == null) {
        return node;
    }

    // Get the right child of the left child
    TreeNode<T> rightChild = leftChild.getRight();

    // Check if the right child is null
    if (rightChild == null) {
        // If the right child is null, then the left child is the new parent
        leftChild.setRight(node);
        node.setLeft(null);
        return leftChild;
    }

    // Get the left child of the right child
    TreeNode<T> leftGrandchild = rightChild.getLeft();

    // Set the left child of the right child to be the left child of the node
    rightChild.setLeft(leftChild);

    // Set the right child of the node to be the right child of the right child
    node.setRight(rightChild);

    // Set the left child of the left child to be the node
    leftChild.setLeft(node);

    // Set the right child of the node to be the left grandchild
    node.setRight(leftGrandchild);

    return node;
}

