public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        if (actualTypeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
            resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
        } else if (actualTypeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) actualTypeArgument;
        } else {
            throw new IllegalArgumentException("Unsupported type argument: " + actualTypeArgument);
        }
    }

    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return Object.class;
    }

    for (Type bound : bounds) {
        if (bound instanceof Class) {
            return (Class<?>) bound;
        } else if (bound instanceof TypeVariable) {
            return resolveTypeVariable((TypeVariable<?>) bound, targetType);
        }
    }

    return null;
}

public void accept(METRICS data) {
    // Check if the data is null
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }

    // Check if the cache is null
    if (cache == null) {
        throw new IllegalStateException("Cache is not initialized");
    }

    // Merge the data with the existing value in the cache
    cache.merge(data.getKey(), data.getValue(), (oldValue, newValue) -> {
        // If the old value is null, return the new value
        if (oldValue == null) {
            return newValue;
        }

        // If the new value is null, return the old value
        if (newValue == null) {
            return oldValue;
        }

        // If the old value is a number, add the new value to the old value
        if (oldValue instanceof Number) {
            return ((Number) oldValue).doubleValue() + ((Number) newValue).doubleValue();
        }

        // If the old value is a string, concatenate the new value to the old value
        if (oldValue instanceof String) {
            return oldValue + newValue;
        }

        // If the old value is an object, merge the new value with the old value
        if (oldValue instanceof Map) {
            return mergeMaps((Map<String, Object>) oldValue, (Map<String, Object>) newValue);
        }

        // If the old value is an array, merge the new value with the old value
        if (oldValue instanceof List) {
            return mergeLists((List<Object>) oldValue, (List<Object>) newValue);
        }

        // If the old value is not a number, string, object, or array, return the old value
        return oldValue;
    });
}

