static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day of the week from the time bucket
    int dayOfWeek = (int) (timeBucket % 100000000);

    // Calculate the year and month from the time bucket
    int year = (int) (timeBucket / 100000000);
    int month = (int) (timeBucket % 100000000) / 10000;

    // Calculate the day of the month from the time bucket
    int day = (int) (timeBucket % 10000);

    // Calculate the new day of the week based on the day step
    dayOfWeek = (dayOfWeek + dayStep) % 7;

    // Calculate the new day of the month based on the day step
    day = day + dayStep;

    // Check if the new day of the month is valid
    if (day > 31) {
        // If the new day of the month is not valid, set it to the last day of the month
        day = 31;
    }

    // Check if the new day of the week is valid
    if (dayOfWeek > 6) {
        // If the new day of the week is not valid, set it to the last day of the week
        dayOfWeek = 6;
    }

    // Return the new time bucket
    return year * 100000000 + month * 10000 + dayOfWeek * 10000 + day;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            char d = str.charAt(i);
            if (Character.isLowSurrogate(d)) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Invalid low surrogate character");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

