public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Check if the path component is an absolute path component
    if (u.getPath().startsWith("/")) {
        // Ignore the leading '/' and start parsing the path segments
        int startIndex = 1;
    } else {
        // Start parsing the path segments from the beginning of the path
        int startIndex = 0;
    }

    // Parse the path segments
    while (startIndex < u.getPath().length()) {
        // Find the next '/' character
        int endIndex = u.getPath().indexOf('/', startIndex);

        // If no '/' character is found, then the remaining part of the path is a path segment
        if (endIndex == -1) {
            endIndex = u.getPath().length();
        }

        // Decode the path segment if necessary
        String pathSegment = u.getPath().substring(startIndex, endIndex);
        if (decode) {
            pathSegment = URLDecoder.decode(pathSegment, "UTF-8");
        }

        // Add the path segment to the list
        pathSegments.add(new PathSegmentImpl(pathSegment));

        // Move to the next path segment
        startIndex = endIndex + 1;
    }

    return pathSegments;
}

