private void putAbstractTypes(int start, int end) {
    // Check if the start and end indices are valid
    if (start < 0 || start >= currentFrame.length || end < 0 || end > currentFrame.length) {
        throw new IllegalArgumentException("Invalid indices: start=" + start + ", end=" + end);
    }

    // Iterate over the types in the current frame and write them to the stack map table entries
    for (int i = start; i < end; i++) {
        VerificationTypeInfo typeInfo = currentFrame[i];
        switch (typeInfo.getTag()) {
            case ITEM_Object:
                stackMapTableEntries.add(new ObjectVariableInfo(typeInfo.getObjectType()));
                break;
            case ITEM_Uninitialized:
                stackMapTableEntries.add(new UninitializedVariableInfo(typeInfo.getUninitializedType()));
                break;
            case ITEM_Long:
            case ITEM_Double:
                // Long and double types take up two slots in the stack map table
                stackMapTableEntries.add(new UninitializedVariableInfo(typeInfo.getUninitializedType()));
                stackMapTableEntries.add(new UninitializedVariableInfo(typeInfo.getUninitializedType()));
                break;
            default:
                stackMapTableEntries.add(new UninitializedVariableInfo(typeInfo.getUninitializedType()));
                break;
        }
    }
}

