public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Desired capacity must be non-negative");
    }

    // Check if the desired capacity is already prime
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // Find the next prime number that is greater than or equal to the desired capacity
    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }

    // If the desired capacity is greater than or equal to 1000, check if the prime number is within 11% of the desired capacity
    if (desiredCapacity >= 1000 && Math.abs(desiredCapacity - prime) / (double) desiredCapacity > 0.11) {
        throw new IllegalArgumentException("The desired capacity must be within 11% of the next prime number");
    }

    return prime;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

