public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder builder = new StringBuilder(str.length());
    boolean wasSlashEscaped = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (wasSlashEscaped) {
            wasSlashEscaped = false;
            switch (c) {
                case 'b':
                    builder.append('\b');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case 'n':
                    builder.append('\n');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                case '\'':
                    builder.append('\'');
                    break;
                case '\"':
                    builder.append('\"');
                    break;
                case 'u':
                    if (i + 4 < str.length() && str.charAt(i + 1) == '\\' && str.charAt(i + 2) == 'u') {
                        String hex = str.substring(i + 3, i + 7);
                        builder.append((char) Integer.parseInt(hex, 16));
                        i += 6;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else if (c == '\\') {
            wasSlashEscaped = true;
        } else {
            builder.append(c);
        }
    }

    if (wasSlashEscaped) {
        throw new Exception("Invalid escape sequence");
    }

    return builder.toString();
}

