private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Check if either set is null or empty
    if (set1 == null || set2 == null || set1.isEmpty() || set2.isEmpty()) {
        return new HashSet<>();
    }

    // Create a new set to store the intersection
    Set<V> intersection = new HashSet<>();

    // Iterate over the elements of set1
    for (V element : set1) {
        // If the element is also in set2, add it to the intersection set
