public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Check if the char buffer is large enough
    if (charBuffer.length < 1024) {
        throw new IllegalArgumentException("Char buffer is too small: " + charBuffer.length);
    }

    // Read the length of the string
    int length = classFileBuffer[constantPoolEntryIndex];

    // Check if the length is valid
    if (length < 0 || length > 65535) {
        throw new IllegalArgumentException("Invalid string length: " + length);
    }

    // Read the string data
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) classFileBuffer[constantPoolEntryIndex + 1 + i];
    }

    // Return the string
    return new String(charBuffer, 0, length);
}

