}

private boolean isShardingKeyIndicesContinuous(String modelName) {
    // Get the sharding key indices for the model
    List<Integer> shardingKeyIndices = getShardingKeyIndices(modelName);

    // Check if the sharding key indices are continuous
    for (int i = 0; i < shardingKeyIndices.size() - 1; i++) {
        if (shardingKeyIndices.get(i) + 1 != shardingKeyIndices.get(i + 1)) {
            return false;
        }
    }

    return true;
}

private List<Integer> getShardingKeyIndices(String modelName) {
    // Get the sharding key for the model
    String shardingKey = getShardingKey(modelName);

    // Split the sharding key into individual indices
    String[] shardingKeyIndices = shardingKey.split(",");

    // Convert the sharding key indices to integers
    List<Integer> shardingKeyIndicesList = new ArrayList<>();
    for (String shardingKeyIndex : shardingKeyIndices) {
        shardingKeyIndicesList.add(Integer.parseInt(shardingKeyIndex));
    }

    return shardingKeyIndicesList;
}

