        sequenceRanges.addAll(profileSequenceRanges);
    }

    // Step 3: Sort the sequence ranges by their start position
    sequenceRanges.sort(Comparator.comparingInt(SequenceRange::getStart));

    // Step 4: Return the sorted sequence ranges
    return sequenceRanges;
}

