public String parseToken(char[] terminators) {
    // Initialize an empty string to store the token
    String token = "";

    // Loop through each character in the input
    for (char c : input) {
        // If the current character is not in the terminators array, add it to the token
        if (!Arrays.asList(terminators).contains(c)) {
            token += c;
        } else {
            // If the current character is in the terminators array, we have reached the end of the token
            break;
        }
    }

