        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Step 1: Remove all nodes from the source list
    ListNode<E> node = list.getFirstNode();
    while (node != null) {
        ListNode<E> nextNode = node.getNext();
        list.removeListNode(node);
        node = nextNode;
    }

    // Step 2: Add all nodes to this list
    node = list.getFirstNode();
    while (node != null) {
        ListNode<E> nextNode = node.getNext();
        addListNode(node);
        node = nextNode;
    }
}

