private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

    for (E edge : graph.edgeSet()) {
        List<Pair<Integer, Integer>> separator = new ArrayList<>();
        separator.add(new Pair<>(edge.getSource(), edge.getTarget()));

        for (E neighbor : graph.neighborsOf(edge.getSource())) {
            if (neighbor != edge.getTarget()) {
                separator.add(new Pair<>(neighbor.getSource(), neighbor.getTarget()));
            }
        }

        separatorList.add(new Pair<>(separator, edge));
    }

    return separatorList;
}

