public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check for null or empty name
    if (nameStart == null || nameStart.length() == 0) {
        return;
    }

    // Check for valid start index
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid start index");
    }

    // Check for valid buffer length
    if (buf.length() < 3) {
        throw new IllegalArgumentException("Buffer length must be at least 3");
    }

    // Abbreviate name
    buf.setCharAt(nameStart, Character.toUpperCase(buf.charAt(nameStart)));
    buf.setCharAt(nameStart + 1, '.');
    buf.setCharAt(nameStart + 2, '.');
}

