private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a complete subgraph
    if (vertices.size() < 2) {
        return false;
    }

    // Check if the subgraph is connected
    if (!graph.isConnected(vertices)) {
        return false;
    }

    // Check if the subgraph is a clique
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

