private void pop(final String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.charAt(0) == 'L') {
        // Pop the type from the output frame stack
        outputFrameStack.pop();
    } else {
        // Pop the method from the output frame stack
        outputFrameStack.pop();

        // Get the argument types from the descriptor
        String[] argumentTypes = descriptor.substring(1).split(";");

        // Pop the arguments from the output frame stack
        for (String argumentType : argumentTypes) {
            outputFrameStack.pop();
        }
    }
}

