public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastSeparatorIndex = indexOfLastSeparator(filename);
    if (lastSeparatorIndex == -1) {
        return -1;
    }

    int extensionIndex = lastSeparatorIndex + 1;
    while (extensionIndex < filename.length() && filename.charAt(extensionIndex) != '.') {
        extensionIndex++;
    }

    if (extensionIndex == filename.length()) {
        return -1;
    }

    return extensionIndex;
}

public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastSeparatorIndex = filename.lastIndexOf('/');
    if (lastSeparatorIndex == -1) {
        lastSeparatorIndex = filename.lastIndexOf('\\');
    }

    return lastSeparatorIndex;
}

