        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event) {
    // Check if there are any connected clients
    if (connectedClients.isEmpty()) {
        return;
    }

    // Create a new message to be sent to each client
    String message = createMessage(event);

    // Send the message to each connected client
    for (WebSocket client : connectedClients) {
        try {
            client.send(message);
        } catch (IOException e) {
            // If there is an error sending the message, remove the client from the list of connected clients
            connectedClients.remove(client);
        }
    }
}

private String createMessage(LoggingEvent event) {
    // Create a new message to be sent to each client
    String message = event.getMessage();

    // Add the log level and timestamp to the message
    message = "[" + event.getLevel() + "] " + event.getTimestamp() + ": " + message;

    return message;
}

